664	        async function createCall() {
665	          const emitter = new EventTarget();
666	
667	          // If we write more than this number, the call will become unwritable.
668	          const highwaterMark = 2;
669	          let writeCounter = 0;
670	
671	          // What has been "written" so far.
672	          const written: any[] = [];
673	
674	          const drain = () => {
675	            writeCounter = 0;
676	            emitter.dispatchEvent(new Event('drain'));
677	          };
678	
679	          const cancel = () => {
680	            emitter.dispatchEvent(new Event(CANCEL_EVENT));
681	          };
682	
683	          const call = {
684	            write: sinon.spy(value => {
685	              // Simulating a writable stream becoming overwhelmed.
686	              if (writeCounter++ < highwaterMark) {
687	                // We can write this value to the stream.
688	                written.push(value);
689	              }
690	              // But as soon as we pass the highwater mark, we can't write anymore.
691	              return writeCounter < highwaterMark;
692	            }),
693	            end: sinon.spy(() => {
694	              written.push('end');
695	            }),
696	            emit: sinon.spy(),
697	            request: sinon.spy(),
698	            metadata: sinon.spy(),
699	            sendMetadata: sinon.spy(),
700	            on: (name, cb) => {
701	              emitter.addEventListener(name, cb);
702	            },
703	            off: (name, cb) => {
704	              emitter.removeEventListener(name, cb);
705	            },
706	            fire: {
707	              drain,
708	              cancel,
709	            },
710	          };
711	
712	          const callback = sinon.spy();
713	
714	          const subject = new Subject<string>();
715	          const handlerResult = Promise.resolve(subject);
716	          const methodHandler = () => handlerResult;
717	
718	          const serviceMethod = await server.createRequestStreamMethod(
719	            methodHandler,
720	            true,
721	          );
722	
723	          const result = serviceMethod(call, callback);
724	
725	          await handlerResult;
726	
727	          return { call, written, result, subject };
728	        }
729	
730	        it('should call write() and end() for streams from promises', async () => {
731	          const handler = async () => ({ test: true });
732	          const fn = server.createRequestStreamMethod(handler, true);
733	          const call = {
734	            on: (event, callback) => {
735	              if (event !== CANCEL_EVENT) {
736	                callback();
737	              }
738	            },
739	            off: sinon.spy(),
740	            end: sinon.spy(),
741	            write: sinon.spy(() => true),
742	          };
743	
744	          await fn(call as any, null);
745	
746	          expect(call.write.called).to.be.true;
747	          expect(call.end.called).to.be.true;
748	        });
749	
